function photoName(x){return String(x||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/['’.]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
function head(p){const id=String(p?.id||'');return esc(nbaRetroHeadshots[id]?'https://cdn.nba.com/headshots/nba/latest/1040x760/'+nbaRetroHeadshots[id]+'.png':p?.headshot||('https://a.espncdn.com/i/headshots/nba/players/full/'+encodeURIComponent(id)+'.png'))}
function photoAttrs(p){const nbaId=nbaRetroHeadshots[String(p?.id||'')]||nbaPhotoIds[photoName(p?.name)];const fallback=nbaId?'https://cdn.nba.com/headshots/nba/latest/1040x760/'+nbaId+'.png':'';return ' data-player-photo="1" data-photo-fallback="'+esc(fallback)+'"'}
document.addEventListener('error',function(event){const img=event.target;if(!(img instanceof HTMLImageElement)||!img.hasAttribute('data-player-photo'))return;const next=img.getAttribute('data-photo-fallback');if(next&&img.src!==next){img.removeAttribute('data-photo-fallback');img.src=next;return}img.removeAttribute('data-player-photo');img.alt='Photo unavailable';img.title='Player photo unavailable';img.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 180"><rect width="160" height="180" rx="12" fill="#202026"/><circle cx="80" cy="62" r="28" fill="#56565f"/><path d="M26 155c2-32 23-51 54-51s52 19 54 51" fill="#56565f"/></svg>')},true);
function action(kind,id){return 'data-go="'+kind+':'+esc(id)+'"'}
function skeleton(n=3){return Array.from({length:n},()=>'<div class="loading"></div>').join('')}
function error(msg){return'<div class="empty">'+esc(msg||'Η πηγή δεδομένων δεν ανταποκρίνεται. Δοκίμασε ξανά.')+'</div>'}
function toast(msg){const x=$('#toast');x.textContent=msg;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2600)}
function getJson(type,params){const u=new URL('/api/data',location.origin);u.searchParams.set('type',type);Object.entries(params||{}).forEach(([k,v])=>u.searchParams.set(k,v));return fetch(u.toString()).then(async r=>{const x=await r.json();if(!r.ok)throw Error(x.error||'Network');return x.data})}
async function loadBase(force){const keys=['scoreboard','teams','standings'];if(force)state.errors={};await Promise.all(keys.map(async t=>{try{const v=await getJson(t,t==='scoreboard'?{date:state.date}:{});if(t==='scoreboard')state.games=v.games||[];if(t==='teams')state.teams=v.teams||[];if(t==='standings')state.groups=v.groups||[];delete state.errors[t]}catch(e){state.errors[t]=e.message}}));$('#sync-status').textContent=state.games.length?'ESPN · UPDATED':'ESPN · CHECK FEEDS';render();if(state.page==='advanced')ensureAdvanced()}
async function loadScores(){try{const d=await getJson('scoreboard',{date:state.date});state.games=d.games||[];delete state.errors.scoreboard}catch(e){state.errors.scoreboard=e.message}render()}
async function loadRoster(id){if(state.rosters[id])return;state.rosters[id]='loading';render();try{state.rosters[id]=await getJson('roster',{id})}catch(e){state.rosters[id]={error:e.message,players:[]}}render()}
async function loadPlayers(){if(state.loadedPlayers||state.loadingPlayers)return;state.loadingPlayers=true;render();try{const d=await getJson('players');state.players=d.players||[];state.loadedPlayers=true;if(d.missing?.length)state.errors.players='Ατελή δεδομένα: δεν απάντησαν '+d.missing.join(', ');else delete state.errors.players}catch(e){state.errors.players=e.message}state.loadingPlayers=false;render()}
async function loadPlayer(id){if(state.details[id])return;state.details[id]={loading:true};render();try{state.details[id]=await getJson('player',{id})}catch(e){state.details[id]={error:e.message}}render()}
async function loadGame(id){if(state.gameDetails[id])return;state.gameDetails[id]={loading:true};render();try{state.gameDetails[id]=await getJson('game',{id})}catch(e){state.gameDetails[id]={error:e.message}}render()}
function route(){const m=(location.hash.replace(/^#\/?/,'')||'home').split('/');state.page=m[0]||'home';state.item=m[1]||'';window.scrollTo({top:0,behavior:'instant'});render();if(state.page==='team'&&state.item){loadRoster(state.item);getHistoricRoster(state.item,state.histYear);window.loadTeamIntel?.(state.item)}if(state.page==='player'&&state.item)getHistoricalPlayer(state.item);if(state.page==='game'&&state.item)loadGame(state.item);if(state.page==='players')loadPlayers();if(state.page==='transactions')window.loadTransactions?.();if(state.page==='player')window.loadTransactions?.();if(state.page==='archive')getHistoricStandings();if(state.page==='forecasts')getForecasts();if(state.page==='search'&&state.q)beginHistoricSearch(state.q);if(['home','games','game'].includes(state.page)){getGreekTV();getForecasts()}if(state.page==='home'){loadSidelineStories();getYesterdayGames()}if(state.page==='advanced')ensureAdvanced();if(state.page==='goat')loadGoat();if(['home','power','team','player'].includes(state.page))loadPower();if(['home','power','team'].includes(state.page))loadMarkets('title');if(state.page==='power'&&pwState.tab==='mvpmarkets')loadMarkets('mvp')}
function go(path){location.hash='/'+path}
function formatStatus(g){return g.state==='post'?'FINAL':g.state==='in'?'LIVE · '+esc(g.status):time(g.date)+' ATH'}
function match(g){return'<button class="game-card" '+action('game',g.id)+'><div class="match-teams">'+logo(g.away)+'<div class="match-names"><div class="match-name">'+name(g.away)+' <small>AWAY</small></div><div class="match-name">'+name(g.home)+' <small>HOME</small></div></div>'+logo(g.home)+'</div><div class="match-detail"><div class="match-score">'+(g.state==='pre'?'VS':esc(g.away?.score??'—')+'<span>:</span>'+esc(g.home?.score??'—'))+'</div><div class="match-status '+(g.state==='in'?'live':'')+'">'+formatStatus(g)+'</div></div><div class="game-insights">'+broadcastLine(g)+forecastLine(g)+'</div></button>'}
function scoreboard(){if(state.errors.scoreboard&&!state.games.length)return error('ESPN scoreboard: '+state.errors.scoreboard);if(!state.games.length)return error('Δεν υπάρχουν αγώνες για την επιλεγμένη ημερομηνία.');return'<div class="game-list">'+state.games.map(match).join('')+'</div>'}
function ticker(){const t=$('#ticker');t.innerHTML=state.games.length?state.games.map(g=>'<button class="tick-game" '+action('game',g.id)+'><div class="tick-head"><span>'+esc(g.away?.abbr)+' @ '+esc(g.home?.abbr)+'</span><span>'+formatStatus(g)+'</span></div><div class="tick-score"><span class="tick-team">'+logo(g.away)+esc(g.away?.abbr)+'</span><span>'+((g.state==='pre')?'—':esc(g.away?.score||'—'))+'</span></div><div class="tick-score"><span class="tick-team">'+logo(g.home)+esc(g.home?.abbr)+'</span><span>'+((g.state==='pre')?'—':esc(g.home?.score||'—'))+'</span></div></button>').join(''):'<div class="ticker-empty">NBA GAME CENTER · Scores load from ESPN</div>'}
function pageTitle(k,title,sub){return'<div class="page-heading"><div><div class="eyebrow">'+k+'</div><h1>'+title+'</h1>'+(sub?'<p>'+sub+'</p>':'')+'</div></div>'}
function statBy(entry,aliases){const a=entry?.stats||[];for(const n of aliases){const x=a.find(z=>z.name===n);if(x&&x.value!==null&&x.value!==undefined)return x.value}return'—'}
function rankedStandings(entries){return [...(entries||[])].sort((a,b)=>{const rank=e=>{for(const key of ['playoffSeed','rank','conferenceRank','divisionRank']){const v=Number(statBy(e,[key]));if(Number.isFinite(v)&&v>0)return v}return null};const ra=rank(a),rb=rank(b);if(ra!==null&&rb!==null&&ra!==rb)return ra-rb;const na=winLossNumbers(a),nb=winLossNumbers(b);const pa=na?.gp?na.w/na.gp:-1,pb=nb?.gp?nb.w/nb.gp:-1;return pb-pa||(nb?.w||0)-(na?.w||0)||(na?.l||0)-(nb?.l||0)})}
function standingSlice(){const vals=state.groups.flatMap(g=>rankedStandings(g.entries).map((x,i)=>({x,i,g:g.name})));return vals.slice(0,6).map(v=>'<div class="newsline"><span><b>'+esc(v.i+1)+'. '+esc(v.x.team?.abbr)+'</b> <span class="muted">· '+esc(v.g)+'</span></span><span class="stat-small">'+esc(statBy(v.x,['wins']))+'-'+esc(statBy(v.x,['losses']))+'</span></div>').join('')||'<div class="muted">Standings unavailable</div>'}
function homeCore(){const live=state.games.filter(g=>g.state==='in').length;return'<div class="hero"><div><div class="eyebrow red">● LIVE LEAGUE INTELLIGENCE</div><h1>THE LEAGUE.<br><em>AFTER DARK.</em></h1><p>Every game. Every roster. Every story in the numbers.</p></div><div class="hero-side"><div class="hero-counter">'+state.games.length.toString().padStart(2,'0')+'</div><div class="hero-counter-label">GAMES · SELECTED DATE</div><div class="hero-counter" style="font-size:24px;color:var(--red);margin-top:18px">'+live+' LIVE</div></div></div>'+
'<section class="section"><div class="section-title"><div><div class="eyebrow">01 / THE WATCHLIST</div><h2>Four to follow</h2></div><button '+action('nav','favorites')+'>Your watchlist →</button></div><div class="spot-grid">'+stars.map((p,i)=>'<button class="spot" '+action('player',p.id)+'><span class="num">0'+(i+1)+'</span><img alt="" loading="lazy" src="'+head(p)+'"'+photoAttrs(p)+'><div class="spot-text"><small>'+esc(p.label)+'</small><b>'+esc(p.name)+'</b></div></button>').join('')+'</div></section>'+
'<section class="section two-col"><div><div class="section-title"><div><div class="eyebrow">02 / COURTSIDE</div><h2>Game center</h2></div><button '+action('nav','games')+'>All games →</button></div>'+scoreboard()+'</div><div><div class="section-title"><div><div class="eyebrow">03 / THE TABLE</div><h2>Conference snapshot</h2></div><button '+action('nav','standings')+'>Full table →</button></div><div class="panel">'+standingSlice()+'</div><div class="panel" style="margin-top:15px"><div class="eyebrow">DATA INTEGRITY</div><p class="muted" style="font-size:12px;line-height:1.7">Real ESPN feeds only. Missing records show as unavailable; no simulated games or ratings.</p></div></div></section>'}
