function extractStats(d){const s=d?.statistics;if(!s?.names||!s?.splits?.length)return{};const split=s.splits.find(x=>/regular season/i.test(x.displayName||''))||s.splits[0];const keys=s.names||[],values=split?.stats||[];const get=k=>{const i=keys.indexOf(k);const v=i<0?null:values[i];return v===null||v===undefined||v===''?'—':v};return{pts:get('avgPoints'),reb:get('avgRebounds'),ast:get('avgAssists'),fg:get('fieldGoalPct')}}
