function teamPage(id){const t=state.teams.find(t=>t.id===id)||Object.values(state.rosters).find(r=>r?.team?.id===id)?.team||{id,name:'NBA team'};const r=state.rosters[id];const entry=state.groups.flatMap(g=>g.entries).find(e=>e.team?.id===id);return'<div class="profile"><div class="profile-info"><div class="eyebrow">FRANCHISE DOSSIER</div><h1>'+esc(t.name)+'</h1><div class="profile-sub">'+esc(t.abbr||'NBA')+' · 2026 / 27</div><p>'+favButton('team',id)+'</p></div>'+ (t.logo?'<img class="hero-team" alt="" src="'+esc(t.logo)+'">':'')+'</div><div class="stat-cards"><div class="stat-card"><b>'+esc(statBy(entry,['wins']))+'</b><span>WINS</span></div><div class="stat-card"><b>'+esc(statBy(entry,['losses']))+'</b><span>LOSSES</span></div><div class="stat-card"><b>'+esc(statBy(entry,['winPercent','winPercentage']))+'</b><span>WIN PCT</span></div><div class="stat-card"><b>'+esc(statBy(entry,['gamesBehind']))+'</b><span>GAMES BACK</span></div><div class="stat-card"><b>'+(winLossNumbers(entry)?.gp??'—')+'</b><span>GAMES PLAYED · GP</span></div></div>'+teamIdentity(t)+window.nbaTeamChampPanel(id)+window.teamIntelPanel(id)+'<section class="section"><div class="section-title"><div><div class="eyebrow">PLAYER PROFILES</div><h2>Players</h2></div></div>'+(!r||r==='loading'?skeleton(3):r.error?error(r.error):r.players?.length?'<div class="player-grid">'+r.players.map(playerCard).join('')+'</div>':error('No roster data returned'))+'</section>'}
function periodBreakdown(d){const sides=d.periods||[];if(!sides.length||!sides.some(x=>x.linescores?.length))return'<div class="muted">Quarter scoring is not available from ESPN for this game.</div>';const periods=[...new Set(sides.flatMap(x=>(x.linescores||[]).map(p=>p.period)))].sort((a,b)=>a-b);return'<section class="section"><div class="section-title"><h2>POINTS BY PERIOD</h2></div><div class="table-wrap"><table><thead><tr><th>TEAM</th>'+periods.map(p=>'<th>'+(p<=4?'Q'+p:'OT'+(p-4))+'</th>').join('')+'<th>TOTAL</th></tr></thead><tbody>'+sides.map(t=>'<tr><td>'+esc(t.team?.abbr||t.homeAway)+'</td>'+periods.map(p=>'<td>'+esc(t.linescores.find(x=>x.period===p)?.points??'—')+'</td>').join('')+'<td>'+t.linescores.reduce((a,b)=>a+b.points,0)+'</td></tr>').join('')+'</tbody></table></div></section>'}
function probabilityHistory(d){const points=(d.winProbability||[]).filter(x=>Number.isFinite(x.homeWinPercentage));if(!points.length)return'<div class="muted">ESPN does not provide a verified in-game win probability timeline for this matchup.</div>';const vals=points.map(x=>x.homeWinPercentage>1?x.homeWinPercentage/100:x.homeWinPercentage).map(x=>Math.max(0,Math.min(1,x)));const w=760,h=190,pad=14;const poly=vals.map((v,i)=>(pad+(i/Math.max(1,vals.length-1))*(w-pad*2)).toFixed(1)+','+(pad+(1-v)*(h-pad*2)).toFixed(1)).join(' ');const home=d.periods?.find(x=>x.homeAway==='home')?.team?.abbr||'HOME';const away=d.periods?.find(x=>x.homeAway==='away')?.team?.abbr||'AWAY';return'<section class="section"><div class="section-title"><h2>WIN PROBABILITY TIMELINE</h2></div><div class="panel"><div class="muted">'+esc(home)+' win probability · 100% top / 0% bottom</div><svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="ESPN in-game win probability history" style="width:100%;height:auto;max-height:240px"><line x1="'+pad+'" y1="'+(h/2)+'" x2="'+(w-pad)+'" y2="'+(h/2)+'" stroke="currentColor" opacity=".25" stroke-dasharray="5 5"/><polyline fill="none" stroke="#d44e5c" stroke-width="3" stroke-linejoin="round" points="'+poly+'"/></svg><div class="muted">Left: tip-off · Right: latest available · Above midpoint: '+esc(home)+' favored · Below: '+esc(away)+' favored</div><div class="muted">Latest ESPN estimate: '+(vals.at(-1)*100).toFixed(1)+'% '+esc(home)+' · '+((1-vals.at(-1))*100).toFixed(1)+'% '+esc(away)+'</div></div></section>'}
function gamePage(id){const g=state.games.find(x=>x.id===id)||(state.yesterdayGames||[]).find(x=>x.id===id);const d=state.gameDetails[id];let title=g?esc(g.away?.abbr)+' at '+esc(g.home?.abbr):'Game detail';let p=pageTitle('BOX SCORE',title,g?dateLabel(g.date)+' · '+formatStatus(g):'');if(g)p+='<div class="panel" style="margin-bottom:20px">'+match(g)+'</div>'+tvProviderPanel(g)+gameForecastPanel(g);if(!d||d.loading)return p+skeleton(3);if(d.error)return p+error(d.error);const sections=(d.players||[]).map(gr=>'<section class="section"><div class="section-title"><h2>'+esc(gr.team?.name||'Team')+'</h2></div>'+gr.groups.map(grp=>'<div class="table-wrap"><table><thead><tr><th>PLAYER</th>'+grp.labels.map(l=>'<th>'+esc(l)+'</th>').join('')+'</tr></thead><tbody>'+grp.athletes.map(a=>'<tr class="click-row" '+action('player',a.athlete?.id)+'><td>'+esc(a.athlete?.name)+'</td>'+a.stats.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('')+'</section>').join('');return p+periodBreakdown(d)+probabilityHistory(d)+(sections||error('ESPN has not published a player box score for this event.'))}
function searchPage(){const q=state.q.trim().toLowerCase();const t=state.teams.filter(x=>(x.name+' '+x.abbr).toLowerCase().includes(q));const p=state.players.filter(x=>(x.name+' '+x.team?.abbr).toLowerCase().includes(q));return pageTitle('SEARCH',esc(state.q))+'<div class="section-title"><h2>Teams</h2></div><div class="team-grid">'+t.map(x=>'<button class="team-card" '+action('team',x.id)+'>'+logo(x)+'<b>'+esc(x.name)+'</b></button>').join('')+'</div><section class="section"><div class="section-title"><h2>Players</h2></div>'+(p.length?'<div class="player-grid">'+p.slice(0,80).map(playerCard).join('')+'</div>':error(state.loadedPlayers?'No matching players':'Player search requires loaded rosters. Open Players to load them.'))+'</section>'}
